export const WIDGET_CSS = "/* Spec: knowledge/components/adyen-agentic-commerce.md */\n/* The widget's own look, inlined into each UI resource: it loads no stylesheet or font. Every\n   control is at least 44 px tall, the touch target in knowledge/policies/ui-ux.md. */\n:root {\n  --bg: #ffffff;\n  --ink: #1d1d1f;\n  --muted: #6b6760;\n  --line: #e5e2dc;\n  --soft: #f5f3ef;\n  --accent: #004526;\n  --on-accent: #ffffff;\n  --ok: #1f6b3a;\n  --bad: #a33a2b;\n  --serif: \"Iowan Old Style\", \"Palatino Linotype\", Palatino, Georgia, serif;\n  --sans: ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  color-scheme: light;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {\n    --bg: #161514;\n    --ink: #f2efe9;\n    --muted: #b4ada3;\n    --line: #3a3733;\n    --soft: #201f1d;\n    --accent: #7cc49a;\n    --on-accent: #0d1f15;\n    --ok: #7cc48b;\n    --bad: #f08a7a;\n    color-scheme: dark;\n  }\n}\n:root[data-theme=\"dark\"] {\n  --bg: #161514;\n  --ink: #f2efe9;\n  --muted: #b4ada3;\n  --line: #3a3733;\n  --soft: #201f1d;\n  --accent: #7cc49a;\n  --on-accent: #0d1f15;\n  --ok: #7cc48b;\n  --bad: #f08a7a;\n  color-scheme: dark;\n}\n* {\n  box-sizing: border-box;\n}\nhtml,\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14px / 1.4 var(--sans);\n  -webkit-font-smoothing: antialiased;\n}\n#app {\n  padding: 10px;\n  max-width: 100%;\n  overflow-x: hidden;\n}\nh3 {\n  font: 600 14px / 1.3 var(--serif);\n  margin: 4px 0 0;\n}\np {\n  margin: 0;\n}\nbutton,\ninput {\n  font: inherit;\n  color: inherit;\n}\nbutton:focus-visible,\ninput:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n.top {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 12px;\n  margin-bottom: 8px;\n}\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-right: auto;\n}\n.mark {\n  display: grid;\n  place-items: center;\n  width: 28px;\n  height: 28px;\n  border-radius: 999px;\n  background: var(--accent);\n  color: var(--on-accent);\n  font: 600 12px / 1 var(--serif);\n}\n.name {\n  font: 600 16px / 1 var(--serif);\n}\n.badge {\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  padding: 1px 7px;\n  font-size: 11px;\n  color: var(--muted);\n}\n.tabs {\n  display: flex;\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  padding: 2px;\n}\n.tab {\n  border: 0;\n  background: transparent;\n  border-radius: 999px;\n  min-height: 36px;\n  padding: 0 12px;\n  font-size: 13px;\n  cursor: pointer;\n}\n.tab[aria-current=\"page\"] {\n  background: var(--accent);\n  color: var(--on-accent);\n}\n.search {\n  display: flex;\n  gap: 8px;\n  margin-bottom: 8px;\n}\n.search input {\n  flex: 1;\n  min-width: 0;\n  min-height: 44px;\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  padding: 0 12px;\n  background: var(--bg);\n}\n.btn {\n  min-height: 44px;\n  border: 1px solid var(--accent);\n  border-radius: 12px;\n  padding: 0 16px;\n  background: var(--accent);\n  color: var(--on-accent);\n  font-weight: 600;\n  cursor: pointer;\n  transition: opacity 150ms ease;\n}\n.btn.ghost {\n  background: transparent;\n  color: var(--accent);\n}\n.btn:disabled,\n.pill:disabled,\n.step:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n/* Cards in a row share one height (ADR-021): 4:3 pictures, titles held to two lines, actions at the\n   bottom, so prices and buttons line up across the rail. */\n.rail {\n  display: flex;\n  align-items: stretch;\n  gap: 8px;\n  overflow-x: auto;\n  scroll-snap-type: x mandatory;\n  list-style: none;\n  margin: 0;\n  padding: 0 0 8px;\n}\n/* About two cards across a phone's panel: the conversation stays in view. */\n.card {\n  flex: 0 0 min(176px, 47%);\n  scroll-snap-align: start;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  border: 1px solid var(--line);\n  border-radius: 14px;\n  padding: 8px;\n}\n.card img,\n.noimg {\n  width: 100%;\n  height: auto;\n  aspect-ratio: 4 / 3;\n  border-radius: 10px;\n  background: var(--soft);\n  object-fit: cover;\n}\n.card h3 {\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  -webkit-line-clamp: 2;\n  line-clamp: 2;\n  overflow: hidden;\n  min-height: 2.6em;\n}\n.card .btn {\n  margin-top: 4px;\n}\n.card .btn:not(.details) {\n  margin-top: auto;\n}\n.price {\n  color: var(--muted);\n}\n.pills {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n.pill {\n  position: relative;\n  min-height: 36px;\n  min-width: 36px;\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  padding: 0 10px;\n  background: transparent;\n  font-size: 13px;\n  cursor: pointer;\n}\n.pill[aria-pressed=\"true\"] {\n  border-color: var(--accent);\n  box-shadow: inset 0 0 0 1px var(--accent);\n}\n.empty,\n.count,\n.muted {\n  color: var(--muted);\n}\n.empty {\n  padding: 16px 0;\n}\n.count {\n  font-size: 12px;\n  margin: 6px 0;\n}\n.lines {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n.line {\n  display: grid;\n  grid-template-columns: 44px 1fr;\n  gap: 2px 10px;\n  align-items: center;\n  padding: 8px 0;\n  border-bottom: 1px solid var(--line);\n}\n.line img,\n.noimg.small {\n  width: 44px;\n  height: 44px;\n  border-radius: 10px;\n  background: var(--soft);\n}\n.line .qty,\n.line > .muted {\n  grid-column: 2;\n}\n.title {\n  font-weight: 600;\n}\n.qty {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.step {\n  position: relative;\n  width: 36px;\n  height: 36px;\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  background: transparent;\n  cursor: pointer;\n}\n.link.quiet {\n  color: var(--muted);\n  font-size: 13px;\n}\n.link {\n  min-height: 44px;\n  border: 0;\n  background: transparent;\n  color: var(--accent);\n  text-decoration: underline;\n  text-underline-offset: 3px;\n  cursor: pointer;\n}\n.totals {\n  margin: 12px 0;\n}\n.row {\n  display: flex;\n  justify-content: space-between;\n  padding: 2px 0;\n}\n.row dt,\n.row dd {\n  margin: 0;\n}\n.row.strong {\n  font-weight: 700;\n}\n.row.ok,\n.muted.ok {\n  color: var(--ok);\n}\n.problems {\n  color: var(--bad);\n  padding-left: 18px;\n}\n.actions {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.cards {\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  padding: 8px 12px;\n  margin: 0;\n}\n.cards legend {\n  font-size: 13px;\n  color: var(--muted);\n}\n.radio {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-height: 44px;\n}\n.radio input {\n  accent-color: var(--accent);\n}\n.note {\n  min-height: 1.4em;\n  margin-top: 10px;\n  font-size: 13px;\n}\n.note.ok {\n  color: var(--ok);\n}\n.note.bad {\n  color: var(--bad);\n}\n.note.info {\n  color: var(--muted);\n}\n@media (prefers-reduced-motion: reduce) {\n  * {\n    transition: none !important;\n    scroll-behavior: auto !important;\n  }\n}\n\n/* Drawn small, touched at 44 px: the hit area reaches 4 px past the edge, and an 8 px gap keeps\n   neighbouring areas apart (UI policy). */\n.pill::after,\n.step::after,\n.tab::after,\n.details::after {\n  content: \"\";\n  position: absolute;\n  inset: -4px;\n}\n.tab,\n.details {\n  position: relative;\n}\n.card .details {\n  margin-top: 0;\n  font-size: 13px;\n}\n/* Safari on a phone zooms into a field under 16 px; the frame's search must not. */\n@media (pointer: coarse) {\n  .search input {\n    font-size: 16px;\n  }\n}\n";
